// GOOD: init clients OUTSIDE the handler — reused across warm invocations
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import com.amazonaws.services.lambda.runtime.*;

public class OrderHandler implements RequestHandler<APIGatewayProxyRequestEvent, APIGatewayProxyResponseEvent> {

    // Static = loaded once per execution context (warm start reuses this)
    private static final DynamoDbClient ddb = DynamoDbClient.builder()
        .httpClientBuilder(software.amazon.awssdk.http.apache.ApacheHttpClient.builder())
        .build();

    private static final String TABLE = System.getenv("ORDERS_TABLE");

    @Override
    public APIGatewayProxyResponseEvent handleRequest(APIGatewayProxyRequestEvent evt, Context ctx) {
        // Just request-specific logic here — no heavy init
        return new APIGatewayProxyResponseEvent().withStatusCode(200);
    }
}
